import{_ as l,C as s,o as e,c as d,j as i,E as r,a as t,a2 as n}from"./chunks/framework.C21TwvGF.js";const T=JSON.parse(`{"title":"10-dars (Mentor). Ranglar nazariyasi va dizayn asoslari (3-qism): O'yin atmosferasiga mos rang palitrasi yaratish","description":"","frontmatter":{"title":"10-dars (Mentor). Ranglar nazariyasi va dizayn asoslari (3-qism): O'yin atmosferasiga mos rang palitrasi yaratish","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"9-sinf (Game)","link":"/mentor/9-sinf-game/"},"week":{"n":4,"link":"/mentor/9-sinf-game/hafta-04/"},"g":10,"title":"Ranglar nazariyasi va dizayn asoslari (3-qism): O'yin atmosferasiga mos rang palitrasi yaratish","lead":"Bir xil o'rmonni kunduzi quvnoq, tunda esa qo'rqinchli qilib ko'rsatish mumkin — faqat ranglarni almashtirib. Bugun o'yiningiz uchun o'z rang palitrangizni yaratamiz.","slide":"/slaydlar/9-sinf-game/hafta-04/dars-1.html","test":"/slaydlar/9-sinf-game/hafta-04/dars-1-test.html","student_link":"/9-sinf-game/hafta-04/dars-1","tabs":[{"g":10,"link":"/mentor/9-sinf-game/hafta-04/dars-1","current":true},{"g":11,"link":"/mentor/9-sinf-game/hafta-04/dars-2","current":false},{"g":12,"link":"/mentor/9-sinf-game/hafta-04/dars-3","current":false}],"prev":null,"next":{"g":11,"title":"O'yin uchun ikonka va spraytlar yaratish (1-qism): Sprayt va ikonka tushunchasi, formatlar (PNG, SVG)","link":"/mentor/9-sinf-game/hafta-04/dars-2"}}},"headers":[],"relativePath":"mentor/9-sinf-game/hafta-04/dars-1.md","filePath":"mentor/9-sinf-game/hafta-04/dars-1.md"}`),h={name:"mentor/9-sinf-game/hafta-04/dars-1.md"},g={class:"blk"},u={id:"dars-rejasi",tabindex:"-1"},y={class:"blk"},k={id:"mentor-konspekti",tabindex:"-1"},m={class:"blk"},q={id:"amaliy-topshiriqlar-va-yechimlar",tabindex:"-1"},c={class:"blk"},p={id:"tezkor-nazorat-savollari",tabindex:"-1"},b={class:"blk"},f={id:"keng-tarqalgan-xatolar-va-ularning-oldini-olish",tabindex:"-1"};function v(_,a,x,z,P,j){const o=s("Icon");return e(),d("div",null,[i("div",g,[i("h2",u,[r(o,{name:"file-text"}),a[0]||(a[0]=t(" Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> Dars rejasi"'},"​",-1))]),a[2]||(a[2]=n("<ul><li><strong>Darsning maqsadi:</strong> O&#39;quvchilarga 8–9-darslarda o&#39;rganilgan rang nazariyasini (rang g&#39;ildiragi, uyg&#39;unlik sxemalari, 60-30-10, Color Picker, Swatches) yagona amaliy jarayonga — o&#39;yin atmosferasiga mos <strong>rang palitrasini</strong> bosqichma-bosqich yaratishga birlashtirishni o&#39;rgatish: kayfiyat taxtasi (mood board), asosiy rang, uyg&#39;unlik, yorug&#39;lik darajasi (value) va kulrang test, soyalarda tus siljitish (hue shifting), to&#39;yinganlik ierarxiyasi, cheklangan palitralar va rang kodlash.</li><li><strong>Kutiladigan natija:</strong> O&#39;quvchilar tanlangan janr va lokatsiya uchun 5–8 rangdan iborat palitra tuzadi; uni Photoshop Swatches panelida guruh qilib saqlaydi va <code>.aco</code> faylga eksport qiladi; palitrani kulrang test orqali tekshiradi; qahramon, dushman va bonus obyektlari fondan ajralib turishini asoslab beradi.</li><li><strong>Vaqt taqsimoti:</strong><ul><li>O&#39;tgan mavzuni takrorlash (HSB, Swatches, Gradient): 10 daqiqa</li><li>Yangi mavzu: Palitra nima va uni yaratishning 6 bosqichi: 20 daqiqa</li><li>Value, hue shifting, to&#39;yinganlik ierarxiyasi: 15 daqiqa</li><li>Janrlar palitralari, cheklangan palitralar, rang kodlash: 10 daqiqa</li><li>Amaliy ish: lokatsiya palitrasini yaratish va kulrang test: 20 daqiqa</li><li>Xulosa: 5 daqiqa</li></ul></li></ul><blockquote><p>Manba: o&#39;quv dasturi — «Ranglar nazariyasi va dizayn asoslari» moduli (3 soat), kutilgan natija: «Atmosfera va dizayn — fon rasmlari, rang palitrasi orqali kayfiyat yaratishni biladi»; o&#39;quv qo&#39;llanma — Color Picker, Swatches, «chegaralangan ranglar palitrasi uyg&#39;un tasvir yaratish uchun ishlatiladi», «rassomlar o&#39;yin olamining kayfiyati va muhitini ... ranglar palitrasi va soyalardan foydalanadilar». Hue shifting va kulrang test — sohadagi umumqabul qilingan amaliy usullar.</p></blockquote><hr>",3))]),i("div",y,[i("h2",k,[r(o,{name:"file-text"}),a[3]||(a[3]=t(" Mentor konspekti ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#mentor-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> Mentor konspekti"'},"​",-1))]),a[5]||(a[5]=n('<h3 id="_1-rang-palitrasi-nima" tabindex="-1">1. Rang palitrasi nima? <a class="header-anchor" href="#_1-rang-palitrasi-nima" aria-label="Permalink to &quot;1. Rang palitrasi nima?&quot;">​</a></h3><p><strong>Rang palitrasi</strong> — o&#39;yin (yoki uning bitta lokatsiyasi) uchun oldindan tanlangan, cheklangan va o&#39;zaro uyg&#39;un ranglar to&#39;plami. Rassom sahnadagi barcha obyektlarni faqat shu ranglar (va ularning och/to&#39;q variantlari) bilan bo&#39;yaydi.</p><p>Nega kerak:</p><ul><li><strong>Yaxlit uslub</strong> — barcha spraytlar, fon va UI bitta o&#39;yinga tegishli ko&#39;rinadi.</li><li><strong>Atmosfera</strong> — ranglar o&#39;yinchida kayfiyat uyg&#39;otadi (qo&#39;rquv, quvonch, sir).</li><li><strong>O&#39;qiluvchanlik</strong> — o&#39;yinchi muhim obyektlarni (qahramon, dushman, bonus) bir qarashda ajratadi.</li><li><strong>Tezlik</strong> — jamoa bir xil ranglardan foydalanadi, har safar rang «o&#39;ylab topilmaydi».</li></ul><h3 id="_2-palitra-yaratishning-6-bosqichi" tabindex="-1">2. Palitra yaratishning 6 bosqichi <a class="header-anchor" href="#_2-palitra-yaratishning-6-bosqichi" aria-label="Permalink to &quot;2. Palitra yaratishning 6 bosqichi&quot;">​</a></h3><ol><li><strong>Kayfiyatni aniqlash.</strong> Bitta jumlada yozing: «Sirli, biroz xavfli, kechki sehrli o&#39;rmon».</li><li><strong>Mood board (kayfiyat taxtasi).</strong> 5–8 ta namunaviy rasm (tabiat fotosuratlari, kinokadrlar, o&#39;yin skrinshotlari) Photoshop&#39;da bitta xolstga yig&#39;iladi.</li><li><strong>Asosiy rang (key color).</strong> Kayfiyatni eng yaxshi ifodalovchi bitta rang; Eyedropper (I) bilan mood board&#39;dan olinadi.</li><li><strong>Uyg&#39;unlik sxemasi.</strong> 8-darsdagi sxemalardan biri asosida qo&#39;shimcha ranglar: analog (tinch), komplementar (keskin kontrast), triadik (yorqin, o&#39;yinchoq).</li><li><strong>Value pog&#39;onalari.</strong> Har bir rangning 2–3 ta yorug&#39;lik darajasi: soya — asosiy — yorug&#39;lik.</li><li><strong>Saqlash va test.</strong> Swatches guruhi, <code>.aco</code> eksport, kulrang test va sinov sahnasi.</li></ol><h3 id="_3-value-yorug-lik-darajasi-va-kulrang-test" tabindex="-1">3. Value (yorug&#39;lik darajasi) va kulrang test <a class="header-anchor" href="#_3-value-yorug-lik-darajasi-va-kulrang-test" aria-label="Permalink to &quot;3. Value (yorug&#39;lik darajasi) va kulrang test&quot;">​</a></h3><p><strong>Value</strong> — rangning qanchalik och yoki to&#39;q ekanligi. O&#39;yinchi obyektlarni avval <strong>rang tusi bilan emas, yorug&#39;lik farqi bilan</strong> ajratadi.</p><p><strong>Kulrang test:</strong> sahna tepasiga <code>Black &amp; White</code> adjustment layer qo&#39;yiladi (yoki nusxada <code>Image → Mode → Grayscale</code>).</p><ul><li>Qahramon fondan kulrangda ham aniq ajralib tursa — palitra yaxshi.</li><li>Hammasi bir xil kulrang dog&#39;ga aylansa — value kontrasti yetarli emas: qahramonni ochroq yoki fonni to&#39;qroq qiling.</li></ul><p>Qoida: <strong>fon — o&#39;rta va past kontrastli</strong>, <strong>o&#39;yin obyektlari — yuqori kontrastli</strong>.</p><h3 id="_4-hue-shifting-—-soyalarda-tus-siljitish" tabindex="-1">4. Hue shifting — soyalarda tus siljitish <a class="header-anchor" href="#_4-hue-shifting-—-soyalarda-tus-siljitish" aria-label="Permalink to &quot;4. Hue shifting — soyalarda tus siljitish&quot;">​</a></h3><p>Boshlovchi xatosi: soya uchun asosiy rangga qora qo&#39;shish → «kir», jonsiz rang.</p><p>Professional usul: to&#39;qlashganda tusni (Hue) <strong>sovuq tomonga</strong> (ko&#39;k/binafsha), ochlashganda <strong>issiq tomonga</strong> (sariq/olovrang) bir oz siljitish.</p><table tabindex="0"><thead><tr><th>Pog&#39;ona</th><th>Hue</th><th>Saturation</th><th>Brightness</th></tr></thead><tbody><tr><td>Yorug&#39;lik</td><td>70° (sariqqa yaqin)</td><td>45%</td><td>90%</td></tr><tr><td>Asosiy yashil</td><td>100°</td><td>60%</td><td>65%</td></tr><tr><td>Soya</td><td>140° (ko&#39;k-yashilga)</td><td>65%</td><td>35%</td></tr></tbody></table><p>Natija — tabiiy va boy ko&#39;rinadigan barg. Color Picker&#39;ning HSB maydonlarida sozlanadi.</p><h3 id="_5-to-yinganlik-ierarxiyasi" tabindex="-1">5. To&#39;yinganlik ierarxiyasi <a class="header-anchor" href="#_5-to-yinganlik-ierarxiyasi" aria-label="Permalink to &quot;5. To&#39;yinganlik ierarxiyasi&quot;">​</a></h3><ul><li><strong>Fon</strong> — past to&#39;yinganlik, uzoqlashgan sari ko&#39;k-kulrangga yaqinlashadi (havo perspektivasi).</li><li><strong>O&#39;yin obyektlari</strong> (platforma, eshik) — o&#39;rtacha to&#39;yinganlik.</li><li><strong>Eng muhim narsalar</strong> (qahramon, bonus, xavf) — eng yuqori to&#39;yinganlik va kontrast.</li></ul><p>Bu 9-darsdagi vizual ierarxiya tamoyilining rangdagi ifodasi.</p><h3 id="_6-janr-va-lokatsiya-palitralari" tabindex="-1">6. Janr va lokatsiya palitralari <a class="header-anchor" href="#_6-janr-va-lokatsiya-palitralari" aria-label="Permalink to &quot;6. Janr va lokatsiya palitralari&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Lokatsiya</th><th>Kayfiyat</th><th>Palitra yo&#39;nalishi</th></tr></thead><tbody><tr><td>Sehrli o&#39;rmon</td><td>sir, mo&#39;jiza</td><td>to&#39;q yashil, ko&#39;k-binafsha + moviy/oltin «sehr» aksentlari</td></tr><tr><td>Muz g&#39;ori</td><td>sovuqlik, yolg&#39;izlik</td><td>oq, och moviy, ko&#39;k; aksent — issiq olovrang (mash&#39;al)</td></tr><tr><td>Cho&#39;l</td><td>issiqlik, charchoq</td><td>qum-sariq, olovrang, terrakota; aksent — firuza (voha)</td></tr><tr><td>Qorong&#39;i yerto&#39;la (horror)</td><td>qo&#39;rquv, taranglik</td><td>past value, xira yashil-kulrang; aksent — qon-qizil</td></tr><tr><td>Kiberpank shahar</td><td>texnologiya, tun</td><td>to&#39;q ko&#39;k-binafsha fon + neon pushti va moviy</td></tr><tr><td>Bolalar platformeri</td><td>quvonch</td><td>yuqori to&#39;yingan triadik: osmon moviy, o&#39;t yashil, quyosh sariq</td></tr></tbody></table><h3 id="_7-cheklangan-palitralar" tabindex="-1">7. Cheklangan palitralar <a class="header-anchor" href="#_7-cheklangan-palitralar" aria-label="Permalink to &quot;7. Cheklangan palitralar&quot;">​</a></h3><p>Ko&#39;p mashhur o&#39;yinlar ataylab kam rang ishlatadi:</p><ul><li><strong>Game Boy</strong> (1989) — atigi 4 ta yashil tusli daraja;</li><li><strong>PICO-8</strong> fantaziya konsoli — 16 ta qat&#39;iy rang;</li><li>zamonaviy pikselli o&#39;yinlar — ko&#39;pincha 16–32 rang.</li></ul><p>Cheklov uslubni yaxlit qiladi. Tayyor palitralar: <strong>Lospec Palette List</strong> (lospec.com/palette-list), <strong>Adobe Color</strong> (color.adobe.com) — HEX kodlarini olish mumkin.</p><h3 id="_8-rang-kodlash-va-qulaylik" tabindex="-1">8. Rang kodlash va qulaylik <a class="header-anchor" href="#_8-rang-kodlash-va-qulaylik" aria-label="Permalink to &quot;8. Rang kodlash va qulaylik&quot;">​</a></h3><p>O&#39;yinchi ma&#39;noni rangdan o&#39;qiydi: qizil — xavf, dushman; yashil — sog&#39;liq; oltin — tanga, mukofot; moviy — mana, sehr, suv. Qoidani butun o&#39;yin davomida <strong>o&#39;zgartirmang</strong>.</p><p>Rang ko&#39;rishida farqi bor o&#39;yinchilar (erkaklarning taxminan 8 foizi) uchun faqat rangga tayanmang: shakl, belgi yoki ikonka qo&#39;shing (dushman ustida ham qizil, ham «!» belgisi).</p><h3 id="_9-photoshop-da-palitrani-saqlash" tabindex="-1">9. Photoshop&#39;da palitrani saqlash <a class="header-anchor" href="#_9-photoshop-da-palitrani-saqlash" aria-label="Permalink to &quot;9. Photoshop&#39;da palitrani saqlash&quot;">​</a></h3><ol><li>Mood board hujjatida Eyedropper (I) bilan rangni oling.</li><li>Swatches panelida <strong>Create new group</strong> → nom: <code>Sehrli_Orman</code>.</li><li>Har bir rang uchun <strong>Create new swatch</strong> (<code>+</code>) → nom: <code>Asosiy_Yashil</code>, <code>Soya_Yashil</code>, <code>Aksent_Oltin</code>.</li><li>Guruhni belgilang → panel menyusi → <strong>Export Selected Swatches...</strong> → <code>Sehrli_Orman.aco</code>.</li><li>Palitra kartasi: xolstda har bir rang kvadrati ostiga HEX kodi yoziladi va PNG qilib jamoaga ulashiladi.</li></ol><hr>',31))]),i("div",m,[i("h2",q,[r(o,{name:"file-text"}),a[6]||(a[6]=t(" Amaliy topshiriqlar va yechimlar ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#amaliy-topshiriqlar-va-yechimlar","aria-label":'Permalink to "<Icon name="file-text" /> Amaliy topshiriqlar va yechimlar"'},"​",-1))]),a[8]||(a[8]=n('<h3 id="_1-topshiriq-kayfiyatdan-palitraga-oson" tabindex="-1">1-topshiriq. Kayfiyatdan palitraga (oson) <a class="header-anchor" href="#_1-topshiriq-kayfiyatdan-palitraga-oson" aria-label="Permalink to &quot;1-topshiriq. Kayfiyatdan palitraga (oson)&quot;">​</a></h3><p>«Muz g&#39;ori» lokatsiyasi uchun kayfiyat jumlasini yozing va 5 rangli palitra taklif qiling (HEX bilan), bitta aksent rangni ko&#39;rsating.</p><p><strong>Yechim:</strong> Kayfiyat: «Sovuq, jim, yolg&#39;iz, lekin go&#39;zal g&#39;or». Palitra (namuna): <code>#0B1E3A</code> (eng to&#39;q soya), <code>#1F4E79</code> (to&#39;q ko&#39;k devor), <code>#5FA8D3</code> (muz), <code>#DFF3FF</code> (yorug&#39;lik/qor), aksent <code>#FF8A3D</code> (mash&#39;al olovi). Aksent — komplementar issiq rang: o&#39;yinchi ko&#39;zi mash&#39;al va yo&#39;lga tortiladi.</p><h3 id="_2-topshiriq-hue-shifting-bilan-3-pog-onali-rang-o-rta" tabindex="-1">2-topshiriq. Hue shifting bilan 3 pog&#39;onali rang (o&#39;rta) <a class="header-anchor" href="#_2-topshiriq-hue-shifting-bilan-3-pog-onali-rang-o-rta" aria-label="Permalink to &quot;2-topshiriq. Hue shifting bilan 3 pog&#39;onali rang (o&#39;rta)&quot;">​</a></h3><p>Qizil olma uchun yorug&#39;lik — asosiy — soya pog&#39;onalarini HSB qiymatlari bilan tuzing. Soya qora qo&#39;shib emas, tus siljitib olinsin.</p><p><strong>Yechim (namuna):</strong></p><ul><li>Yorug&#39;lik: H 15°, S 55%, B 95% (olovrang tomonga);</li><li>Asosiy: H 0°, S 80%, B 80%;</li><li>Soya: H 340°, S 75%, B 45% (binafsha-qizil tomonga). Tekshirish: uchala kvadrat yonma-yon qo&#39;yilganda soya «kir jigarrang» emas, to&#39;q gilos rangida ko&#39;rinadi.</li></ul><h3 id="_3-topshiriq-kulrang-test-o-rta" tabindex="-1">3-topshiriq. Kulrang test (o&#39;rta) <a class="header-anchor" href="#_3-topshiriq-kulrang-test-o-rta" aria-label="Permalink to &quot;3-topshiriq. Kulrang test (o&#39;rta)&quot;">​</a></h3><p>Fon (o&#39;rmon) va qahramon spraytiga palitrangizni qo&#39;llang. <code>Black &amp; White</code> adjustment layer bilan sahnani tekshiring. Qahramon ajralib turmasa, nima o&#39;zgartiriladi?</p><p><strong>Yechim:</strong></p><ol><li>Layers panelida eng yuqoriga <code>Black &amp; White</code> adjustment layer qo&#39;shiladi.</li><li>Qahramon va fon bir xil kulrangda bo&#39;lsa: qahramon ranglarining Brightness qiymati 15–25% ko&#39;tariladi yoki fon Brightness i tushiriladi; fon to&#39;yinganligi kamaytiriladi.</li><li>Qayta test: qahramon siluyeti aniq ko&#39;rinsa — bajarildi. Adjustment layer ko&#39;z belgisi bilan o&#39;chiriladi.</li></ol><h3 id="_4-topshiriq-ikki-lokatsiya-—-bitta-o-yin-qiyin" tabindex="-1">4-topshiriq. Ikki lokatsiya — bitta o&#39;yin (qiyin) <a class="header-anchor" href="#_4-topshiriq-ikki-lokatsiya-—-bitta-o-yin-qiyin" aria-label="Permalink to &quot;4-topshiriq. Ikki lokatsiya — bitta o&#39;yin (qiyin)&quot;">​</a></h3><p>Bir o&#39;yinning ikki darajasi uchun palitra: «Kunduzgi qishloq» va «Tungi qishloq». Ikkalasida ham qahramon ranglari (3 ta) bir xil qolsin. Swatches da 2 guruh qilib saqlang va <code>.aco</code> ga eksport qiling.</p><p><strong>Yechim:</strong></p><ul><li>Qahramon (o&#39;zgarmas): qizil plash <code>#D7263D</code>, teri <code>#F2C29B</code>, to&#39;q kontur <code>#2B1B17</code>.</li><li>Kunduz: osmon <code>#8FD3FF</code>, o&#39;t <code>#6BBF59</code>, tom <code>#C8553D</code>, yo&#39;l <code>#E9D8A6</code>, soya <code>#3B6E57</code>.</li><li>Tun: osmon <code>#141B41</code>, o&#39;t <code>#2C4A52</code>, tom <code>#5A2E3A</code>, yo&#39;l <code>#6C6F7F</code>, aksent (deraza nuri) <code>#FFD166</code>.</li><li>Guruhlar: <code>Qishloq_Kun</code>, <code>Qishloq_Tun</code>; har biri alohida <code>.aco</code>. Asosiy fikr: tun palitrasida qahramon qizili yanada kuchli ajralib turadi — tun ranglari past to&#39;yinganlik va past value&#39;da.</li></ul><hr>',16))]),i("div",c,[i("h2",p,[r(o,{name:"file-text"}),a[9]||(a[9]=t(" Tezkor nazorat savollari ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#tezkor-nazorat-savollari","aria-label":'Permalink to "<Icon name="file-text" /> Tezkor nazorat savollari"'},"​",-1))]),a[11]||(a[11]=n("<ol><li>Rang palitrasi nima va u o&#39;yinga nima beradi? <ul><li><em>Javob:</em> Oldindan tanlangan cheklangan uyg&#39;un ranglar to&#39;plami; yaxlit uslub, atmosfera va o&#39;qiluvchanlik beradi.</li></ul></li><li>Kulrang test nima uchun qilinadi? <ul><li><em>Javob:</em> Obyektlar rangsiz, faqat yorug&#39;lik (value) farqi bilan ham ajralib turishini tekshirish uchun.</li></ul></li><li>Hue shifting nima? <ul><li><em>Javob:</em> Soya tomonda tusni sovuqroqqa, yorug&#39;lik tomonda issiqroqqa siljitish (qora/oq qo&#39;shish o&#39;rniga).</li></ul></li><li>Fon va qahramonning to&#39;yinganligi qanday bo&#39;lishi kerak? <ul><li><em>Javob:</em> Fon — pastroq to&#39;yinganlik va kontrast, qahramon va muhim obyektlar — yuqori.</li></ul></li><li>Photoshop&#39;da palitra qaysi formatda eksport qilinadi? <ul><li><em>Javob:</em> <code>.aco</code> (Swatches → Export Selected Swatches).</li></ul></li></ol><hr>",2))]),i("div",b,[i("h2",f,[r(o,{name:"file-text"}),a[12]||(a[12]=t(" Keng tarqalgan xatolar va ularning oldini olish ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#keng-tarqalgan-xatolar-va-ularning-oldini-olish","aria-label":'Permalink to "<Icon name="file-text" /> Keng tarqalgan xatolar va ularning oldini olish"'},"​",-1))]),a[14]||(a[14]=n("<ul><li><strong>Juda ko&#39;p rang:</strong> 20–30 ta tasodifiy rang uslubni buzadi. Lokatsiya uchun 5–8 ta asosiy rang yetarli.</li><li><strong>Soyani qora bilan qilish:</strong> rang «kir» bo&#39;ladi — hue shifting ishlating.</li><li><strong>Hamma narsa bir xil yorqin:</strong> ko&#39;z qayerga qarashni bilmaydi — faqat muhim obyektlar eng yorqin.</li><li><strong>Faqat rang bilan ma&#39;no berish:</strong> shakl va belgi ham qo&#39;shing.</li><li><strong>Palitrani saqlamaslik:</strong> keyingi darslarda ikonka va spraytlar shu palitrada chiziladi — <code>.aco</code> faylni saqlang.</li></ul>",1))])])}const A=l(h,[["render",v]]);export{T as __pageData,A as default};
